// ********************** GOOGLE CLOUD STORAGE **********************

private static final List<String> GOOGLE_BUCKET_CONFIG_KEYS = ["google.cloud.storage.bucketName", "google.bucket.name"]
private static final String GOOGLE_BUCKET_ENV_KEY = "GOOGLE_CLOUD_STORAGE_BUCKET"
private static final List<String> GOOGLE_CREDENTIAL_RESOURCE_CONFIG_KEYS = ["google.cloud.storage.credentialResource", "google.credential.resource"]
private static final String GOOGLE_CREDENTIAL_RESOURCE_ENV_KEY = "GOOGLE_CLOUD_STORAGE_CREDENTIAL_RESOURCE"
private static final String DEFAULT_GOOGLE_CREDENTIAL_RESOURCE = "google-cloud-service-account.json"
private static final List<String> GOOGLE_PROJECT_ID_CONFIG_KEYS = ["google.cloud.storage.projectId", "google.project.id"]
private static final String GOOGLE_PROJECT_ID_ENV_KEY = "GOOGLE_CLOUD_PROJECT"

/**
 * Reads a Google Cloud setting from the Grails configuration falling back to a system property
 * and finally to an environment variable, so that the value can also be supplied by the runtime.
 */
private static String fetchGoogleSetting(List<String> configKeys, String environmentKey) {
    def value = null
    try {
        def flatConfig = Holders.getFlatConfig()
        configKeys.each { String configKey ->
            if (!value || StringUtils.isBlank(value.toString()))
                value = flatConfig?.get(configKey)
        }
    } catch (Exception e) {
        value = null
    }
    if (!value || StringUtils.isBlank(value.toString()))
        value = System.getProperty(environmentKey)
    if (!value || StringUtils.isBlank(value.toString()))
        value = System.getenv(environmentKey)
    value && StringUtils.isNotBlank(value.toString()) ? value.toString() : null
}

private static String getGoogleBucketName() {
    fetchGoogleSetting(GOOGLE_BUCKET_CONFIG_KEYS, GOOGLE_BUCKET_ENV_KEY)
}

/**
 * The service account of the deployed instance is made available as a classpath resource,
 * hence no credential is ever kept within the code base. Whenever the resource is absent the
 * application default credential of the runtime is used.
 */
private static InputStream getGoogleCredentialStream() {
    String resourceName = fetchGoogleSetting(GOOGLE_CREDENTIAL_RESOURCE_CONFIG_KEYS, GOOGLE_CREDENTIAL_RESOURCE_ENV_KEY) ?: DEFAULT_GOOGLE_CREDENTIAL_RESOURCE
    InputStream credentialStream = null
    try {
        credentialStream = Thread.currentThread().getContextClassLoader()?.getResourceAsStream(resourceName)
        if (!credentialStream)
            credentialStream = HelperMethod.class.getResourceAsStream("/${resourceName}")
    } catch (Exception e) {
        credentialStream = null
    }
    credentialStream
}

private static Storage getGoogleStorageService() {
    StorageOptions.Builder optionsBuilder = StorageOptions.newBuilder()
    String projectId = fetchGoogleSetting(GOOGLE_PROJECT_ID_CONFIG_KEYS, GOOGLE_PROJECT_ID_ENV_KEY)
    if (projectId)
        optionsBuilder.setProjectId(projectId)
    InputStream credentialStream = getGoogleCredentialStream()
    if (credentialStream) {
        try {
            optionsBuilder.setCredentials(GoogleCredentials.fromStream(credentialStream))
        } finally {
            credentialStream.close()
        }
    }
    optionsBuilder.build().getService()
}

private static BlobId getGoogleBlobId(String path) {
    BlobId.of(getGoogleBucketName(), path)
}

public static Boolean uploadObjectToGoogle(File file, String path) {
    Boolean isFileUploaded = Boolean.FALSE
    if (path && StringUtils.isNotBlank(path)) {
        try {
            Storage storage = getGoogleStorageService()
            BlobInfo blobInfo = BlobInfo.newBuilder(getGoogleBlobId(path)).build()
            storage.create(blobInfo, file.getBytes())
            isFileUploaded = Boolean.TRUE
        }
        catch (Exception e) {
            log.error("Exception while uploading file to Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    isFileUploaded
}

public static InputStream downloadObjectFromGoogle(String path) {
    InputStream inputStream = null
    if (path && StringUtils.isNotBlank(path)) {
        try {
            Storage storage = getGoogleStorageService()
            BlobId blobId = getGoogleBlobId(path)
            byte[] content = null
            try {
                Blob blob = storage.get(blobId)
                if (blob)
                    content = blob.getContent()
            } catch (Exception e) {
                content = null
            }
            if (content == null)
                content = storage.readAllBytes(blobId)
            if (content != null)
                inputStream = new ByteArrayInputStream(content)
        }
        catch (Exception e) {
            log.error("Exception while downloading file from Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    inputStream
}

public static Boolean deleteObjectFromGoogle(String path) {
    Boolean isFileDeleted = Boolean.FALSE
    if (path && StringUtils.isNotBlank(path)) {
        try {
            Storage storage = getGoogleStorageService()
            isFileDeleted = storage.delete(getGoogleBlobId(path)) as Boolean
        }
        catch (Exception e) {
            log.error("Exception while deleting file from Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    isFileDeleted
}

public static Boolean uploadObjectToGoogleCloud(File file, String path) {
    uploadObjectToGoogle(file, path)
}

public static InputStream downloadObjectFromGoogleCloud(String path) {
    downloadObjectFromGoogle(path)
}

public static Boolean deleteObjectFromGoogleCloud(String path) {
    deleteObjectFromGoogle(path)
}

public static void uploadObjectToLocalOrGoogle(File pdfFile, String documentPath = null) {
    if (GrailsUtil.developmentEnv) {
        log.info("=== Requesting file to be uploaded on Local location ===>>> ${documentPath}")
        File file = new File(documentPath)
        FileUtils.writeByteArrayToFile(file, pdfFile.getBytes())
    } else {
        log.info("=== Requesting file to be uploaded on Google Cloud Storage location ===>>> ${documentPath}")
        uploadObjectToGoogle(pdfFile, documentPath)
    }
}

public static void uploadObjectToLocalOrGoogleCloud(File pdfFile, String documentPath = null) {
    uploadObjectToLocalOrGoogle(pdfFile, documentPath)
}

