import com.google.cloud.storage.*
import com.google.cloud.storage.contrib.nio.testing.LocalStorageHelper
import org.apache.commons.lang.StringUtils

class GcsApiCheck {
    static Storage storage = LocalStorageHelper.getOptions().getService()
    static String bucket = "test-bucket"

    static BlobId blobId(String path) { BlobId.of(bucket, path) }

    static Boolean upload(File file, String path) {
        Boolean isFileUploaded = Boolean.FALSE
        if (path && StringUtils.isNotBlank(path)) {
            try {
                BlobInfo blobInfo = BlobInfo.newBuilder(blobId(path)).build()
                storage.create(blobInfo, file.getBytes())
                isFileUploaded = Boolean.TRUE
            } catch (Exception e) { println "upload err: $e" }
        }
        isFileUploaded
    }

    static InputStream download(String path) {
        InputStream inputStream = null
        if (path && StringUtils.isNotBlank(path)) {
            try {
                BlobId id = blobId(path)
                byte[] content = null
                try {
                    Blob blob = storage.get(id)
                    if (blob) content = blob.getContent()
                } catch (Exception e) { content = null }
                if (content == null) content = storage.readAllBytes(id)
                if (content != null) inputStream = new ByteArrayInputStream(content)
            } catch (Exception e) { println "download err: $e" }
        }
        inputStream
    }

    static Boolean del(String path) {
        Boolean deleted = Boolean.FALSE
        if (path && StringUtils.isNotBlank(path)) {
            try { deleted = storage.delete(blobId(path)) as Boolean } catch (Exception e) { println "del err: $e" }
        }
        deleted
    }

    static void main(String[] a) {
        File f = File.createTempFile("stmt", ".pdf")
        byte[] bytes = "hello-statement-bytes".getBytes("UTF-8")
        f.bytes = bytes
        String path = "static/Success_Files/Client_1/08-Aug-2026/ICICI/application-pdf/abc123_stmt.pdf"
        assert upload(f, path)
        InputStream is = download(path)
        assert is != null
        assert is.bytes == bytes
        // blank / null path no-ops
        assert upload(f, "") == Boolean.FALSE
        assert upload(f, "   ") == Boolean.FALSE
        assert upload(f, null) == Boolean.FALSE
        assert download("") == null
        assert download(null) == null
        assert del("") == Boolean.FALSE
        // object name preserved
        assert storage.get(BlobId.of(bucket, path)) != null
        assert storage.get(BlobId.of(bucket, path)).getName() == path
        assert del(path)
        println "ALL GCS API CHECKS PASSED"
    }
}
